def reconstruct_edge_count(deck, n):
    total = sum(card.edge_count() for card in deck)
    return total // (n - 2)

def reconstruct_degree_sequence(deck, n):
    total_edges = reconstruct_edge_count(deck, n)
    return sorted([total_edges - c.edge_count() for c in deck], reverse=True)

def detect_regularity(deck, n):
    counts = [c.edge_count() for c in deck]
    if len(set(counts)) == 1:
        total = sum(counts) // (n - 2)
        return True, total - counts[0]
    return False, -1
